import{_ as e,c as t,o as r,ag as o}from"./chunks/framework.C7v41-tM.js";const _=JSON.parse('{"title":"工具很多时，怎样让 Agent 选得更稳","description":"","frontmatter":{},"headers":[],"relativePath":"technical/tool-search-practice.md","filePath":"technical/tool-search-practice.md","lastUpdated":null}'),l={name:"technical/tool-search-practice.md"};function i(n,a,c,h,p,s){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="工具很多时-怎样让-agent-选得更稳" tabindex="-1">工具很多时，怎样让 Agent 选得更稳 <a class="header-anchor" href="#工具很多时-怎样让-agent-选得更稳" aria-label="Permalink to &quot;工具很多时，怎样让 Agent 选得更稳&quot;">​</a></h1><p>先建立可信工具目录和权限边界，再改善检索。把所有工具说明塞进提示词，既占上下文，也容易让名称相近的能力混淆。本文讲实现步骤；协议定义见 <a href="https://github.com/lixudong1649/jdp-wiki/blob/main/content/terms/mcp.md" target="_blank" rel="noreferrer">MCP 条目</a>。</p><h2 id="先把-查-和-改-分清" tabindex="-1">先把“查”和“改”分清 <a class="header-anchor" href="#先把-查-和-改-分清" aria-label="Permalink to &quot;先把“查”和“改”分清&quot;">​</a></h2><p>教学例子：工具目录同时有“查订单”“改订单备注”和“取消订单”。用户只问订单状态时，候选首先应包含查询能力，不能因为描述都出现“订单”就将三个动作视为等价。</p><p>工具元数据需要稳定 ID、来源、版本、用途、参数 Schema、权限和可用状态。名称和描述要明确动作与边界；模型不能靠猜测生成一个不存在的函数。</p><h2 id="最小流程" tabindex="-1">最小流程 <a class="header-anchor" href="#最小流程" aria-label="Permalink to &quot;最小流程&quot;">​</a></h2><ol><li>按可信身份限定可见工具范围。</li><li>使用任务、必要上下文和最近结果形成检索查询。</li><li>从关键词检索起步，选出候选并加载当前完整定义。</li><li>模型提出工具和参数；执行入口再次校验权限、参数与业务条件。</li><li>执行真实实现，将结果带回下一轮；无匹配则有限次扩搜或澄清。</li></ol><p>关键词召回不足时再加入语义检索或重排。没有对所有系统适用的工具数量阈值或最佳 Top-K；应同时看候选覆盖率、误选率、上下文开销和调用延迟。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><p>“被检索到”不等于获准执行；允许某个工具也不等于允许它访问所有记录。权限撤销、工具版本变化和索引缓存都需要同步处理。</p><p>工具目录里只保存能力说明，凭据不进入检索文本。第三方工具描述属于外部数据，不得覆盖系统授权政策。</p><p>参考：<a href="https://docs.langchain.com/oss/python/langchain/middleware/built-in" target="_blank" rel="noreferrer">LangChain 中间件</a>、<a href="https://modelcontextprotocol.io/docs/learn/architecture" target="_blank" rel="noreferrer">MCP 架构</a>。流程为应用设计建议，整理：2026-10-14。</p>',12)])])}const m=e(l,[["render",i]]);export{_ as __pageData,m as default};
